package ro.leo.keypad;
import java.text.Normalizer;
import java.util.*;

/** Small original word list; no typed-text learning, network or imported proprietary dictionary. */
final class PredictiveDictionary {
    private static final String WORDS="da nu eu tu el ea noi voi ei ele și în la de pe cu un o este sunt e am ai are avem aveți au eram era eram fost fi fie bine bun bună salut mulțumesc te rog scuze acum aici acolo azi mâine ieri dimineață seară noapte zi zile timp când unde cum cine ce care cât câte câtă pentru din după înainte până între despre fără sau dar dacă să mai foarte prea doar tot toate toți nimic ceva cineva nimeni meu mea mei mele tău ta lui lor nostru noastră vostru voastră acesta aceasta acest aceea aici acasă casă masă apă cafea ceai lapte pâine mâncare foame sete frig cald rece mare mic mare mult puțin frumos frumoasă repede încet nou vechi nouă număr telefon mesaj apel contact rețea internet cartelă sunet muzică video poză imagine galerie ceas alarmă calendar notă fișier folder setări ecran lumină baterie încărcare calculator convertor descarcă descărcare înregistrare pauză oprește pornește salvează șterge înapoi meniu opțiuni alege trimite primit răspunde ajung ajuns vin vii vine venim veniți veni plec plecat pleacă merg merge mergem drum stradă oraș sat tren autobuz mașină gară muncă serviciu școală facultate magazin spital medic familie prieten prietenă mamă tată copil copii frate soră soț soție om oameni România română român București luni marți miercuri joi vineri sâmbătă duminică ianuarie februarie martie aprilie mai iunie iulie august septembrie octombrie noiembrie decembrie oră minut minute secundă secunde an ani lună săptămână weekend test primit funcționează perfect probabil sigur posibil poate trebuie vreau vrei vrem vreți vrea pot poți putem puteți poate știu știi știm știe văd vezi vedem vede aud auzi auzim aude spun spui spune scriu scrii scrie citesc citești citește găsesc găsești găsește deschid deschizi deschide închid închizi închide fac faci face făcut ajut ajutor nevoie gata liber ocupat rău ușor greu lung scurt stânga dreapta sus jos centru normal silențios vibrații blocat deblocat taste tastatură spațiu literă cuvânt text parolă notițe favorite continuă anulează confirmă atenție eroare disponibil indisponibil local mobil simplu rapid lent fluid stabil adevărat fals prima primul ultimul ultima doi două trei patru cinci șase șapte opt nouă zece sută mie zero unu una hello thanks okay home phone message music good morning night yes no";
    private static final ArrayList<String> words=new ArrayList<String>();
    private static final ArrayList<String> codes=new ArrayList<String>();
    static { HashSet<String> seen=new HashSet<String>();for(String word:WORDS.split(" +"))if(seen.add(word)){words.add(word);codes.add(digits(word));} }
    static String digits(String text){String s=Normalizer.normalize(text.toLowerCase(Locale.ROOT),Normalizer.Form.NFD).replaceAll("\\p{M}","");StringBuilder b=new StringBuilder();for(int i=0;i<s.length();i++){char c=s.charAt(i);if(c>='a'&&c<='z')b.append(c<='c'?'2':c<='f'?'3':c<='i'?'4':c<='l'?'5':c<='o'?'6':c<='s'?'7':c<='v'?'8':'9');else return "";}return b.toString();}
    static List<String> candidates(String sequence){ArrayList<String> result=new ArrayList<String>();if(sequence.isEmpty())return result;
        for(int pass=0;pass<2&&result.size()<12;pass++)for(int i=0;i<words.size()&&result.size()<12;i++){String code=codes.get(i);if((pass==0?code.equals(sequence):code.length()>sequence.length()&&code.startsWith(sequence)))result.add(words.get(i));}
        if(result.isEmpty())result.add(sequence);return result;
    }
}
